from datetime import datetime, timedelta
from zoneinfo import ZoneInfo

DAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]

settings = api.extension.settings() or {}
zone_name = settings.get("time_zone") or "Australia/Sydney"
try:
    zone = ZoneInfo(zone_name)
except Exception:
    zone_name = "Australia/Sydney"
    zone = ZoneInfo(zone_name)

checkin_day = settings.get("checkin_day") if settings.get("checkin_day") in DAYS else "monday"
checkin_time = settings.get("checkin_time") or "09:00"
try:
    due_hour, due_minute = [int(x) for x in checkin_time.split(":")]
except Exception:
    due_hour, due_minute = 9, 0

now = datetime.now(zone)
force = bool(params.get("run_now"))
is_due = DAYS[now.weekday()] == checkin_day and now.hour == due_hour and (now.minute // 15) == (due_minute // 15)

reminded = []
skipped_reason = ""

if not is_due and not force:
    skipped_reason = f"Not check-in time yet in {zone_name}."
else:
    week_start = (now - timedelta(days=now.weekday())).date()
    week_label = week_start.isoformat()

    team_ids = settings.get("team_member_ids")
    if not isinstance(team_ids, list) or not team_ids:
        skipped_reason = "No team members are set in setup, so nobody was reminded."
    else:
        users = api.users.list() or []
        by_id = {u.get("id"): u for u in users if isinstance(u, dict)}

        # Who has already checked in this week
        done = set()
        cursor = None
        for _ in range(10):
            args = {"type_slug": "check_ins", "limit": 200}
            if cursor is not None:
                args["cursor"] = cursor
            page = api.records.list(**args) or {}
            for r in page.get("records", []):
                fields = r.get("fields") or r.get("values") or r
                if str(fields.get("week_starting") or "")[:10] == week_label:
                    done.add(str(fields.get("person") or "").strip().lower())
            cursor = page.get("nextCursor")
            if cursor is None:
                break

        for uid in team_ids:
            user = by_id.get(uid)
            if not user or user.get("is_external"):
                continue
            names = {str(user.get(k) or "").strip().lower() for k in ("name", "display_name", "email")} - {""}
            if names & done:
                continue
            person = user.get("name") or user.get("display_name") or user.get("email") or "there"
            title = f"Your weekly check-in ({week_label})"
            existing = api.workq.list(search=title) or []
            if any(uid in (item.get("assignee_ids") or []) for item in existing if isinstance(item, dict)):
                continue
            item = api.workq.create(
                title=title,
                scope="me",
                priority="medium",
                assignee_ids=[uid],
                description=(
                    f"Hi {person.split(' ')[0]}, your check-in for the week of {week_label} is waiting. "
                    "It takes about a minute: open the Weekly check-in form attached to this item."
                ),
            )
            api.workq.attach_form(todo_id=item["id"], form_id=params["checkin_form"])
            reminded.append(person)

reminded_count = len(reminded)
summary = (
    f"Reminded {reminded_count}: " + ", ".join(reminded) if reminded else (skipped_reason or "Everyone has checked in.")
)
